INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"668d0951-6c79-5f52-a1c6-bf24e87de49a","title":"Mathematics · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"R5 000 grows at 10% per year compounded annually. Its value after 2 years is…","options":["R6 050","R6 000","R5 500","R7 000"],"correct_index":0,"explanation":"A=P(1+i)ⁿ = 5 000(1.10)² = 6 050. Compound interest includes interest on the first year's interest.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A test for a condition has P(positive and condition)=0.18 and P(positive)=0.30. Find P(condition given positive).","options":["0.054","0.48","0.12","0.60"],"correct_index":3,"explanation":"Conditional probability divides the intersection by the conditioning event: 0.18/0.30 = 0.60.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the derivative of f(x) = 2x³ − 5x² + 4.","options":["6x² − 5x","2x² − 10x + 4","6x² − 10x","6x³ − 10x²"],"correct_index":2,"explanation":"Apply the power rule term by term. A constant's derivative is zero; the exponent decreases by one.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For x² − 4x + 3 = 0, what is the discriminant?","options":["28","−4","16","4"],"correct_index":3,"explanation":"Δ=b²−4ac = (−4)²−4(1)(3)=4. It is positive, so the quadratic has two distinct real roots.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A quadratic sequence has T₁=2, T₂=6 and T₃=12, with constant second difference 2. Which term is the first greater than 100?","options":["T₉=90","T₁₁=132","T₁₀=110","T₁₂=156"],"correct_index":2,"explanation":"The sequence is Tₙ=n²+n. Solve n(n+1)>100 for positive integers: T₉=90 and T₁₀=110. Although later terms also exceed 100, the first is term 10.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","math"],"metadata":{"term":2,"focus":"Mixed revision: Finance, regression and counting; Integrated examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"febb688c-9d1f-51f1-b090-91879ccc9b2a","title":"Mathematics · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"Find the gradient of the tangent to f(x) = x³ − 2x at x = 2.","options":["6","4","12","10"],"correct_index":3,"explanation":"Differentiate first: f′(x)=3x²−2. Then f′(2)=12−2=10. f(2)=4 is the function value, not the gradient.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For f(x) = x² − 4x, where is the stationary point?","options":["x = 4","x = 0","x = 2","x = −2"],"correct_index":2,"explanation":"At a stationary point f′(x)=0. Since f′(x)=2x−4, solve 2x−4=0 to get x=2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"Find the derivative of f(x) = 2x³ − 5x² + 4.","options":["6x² − 5x","2x² − 10x + 4","6x² − 10x","6x³ − 10x²"],"correct_index":2,"explanation":"Apply the power rule term by term. A constant's derivative is zero; the exponent decreases by one.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For x² − 4x + 3 = 0, what is the discriminant?","options":["28","−4","16","4"],"correct_index":3,"explanation":"Δ=b²−4ac = (−4)²−4(1)(3)=4. It is positive, so the quadratic has two distinct real roots.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A quadratic sequence has T₁=2, T₂=6 and T₃=12, with constant second difference 2. Which term is the first greater than 100?","options":["T₉=90","T₁₁=132","T₁₀=110","T₁₂=156"],"correct_index":2,"explanation":"The sequence is Tₙ=n²+n. Solve n(n+1)>100 for positive integers: T₉=90 and T₁₀=110. Although later terms also exceed 100, the first is term 10.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","math"],"metadata":{"term":3,"focus":"Mixed revision: Geometry and differential calculus; Integrated examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"f2b3b029-f78b-5a6d-8ec3-378cefd21415","title":"Mathematics · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Mathematics","grade":"Grade 12","questions":[{"question":"Find the gradient of the tangent to f(x) = x³ − 2x at x = 2.","options":["6","4","12","10"],"correct_index":3,"explanation":"Differentiate first: f′(x)=3x²−2. Then f′(2)=12−2=10. f(2)=4 is the function value, not the gradient.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"For f(x) = x² − 4x, where is the stationary point?","options":["x = 4","x = 0","x = 2","x = −2"],"correct_index":2,"explanation":"At a stationary point f′(x)=0. Since f′(x)=2x−4, solve 2x−4=0 to get x=2.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A regression model is ŷ = 2x + 5. Predict y when x = 4.","options":["11","13","8","18"],"correct_index":1,"explanation":"Substitute x=4: ŷ=2(4)+5=13. This is a model prediction, not a guaranteed observed value.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"How many 3-digit codes can be formed from 0–9 if repetition is allowed and a code may start with 0?","options":["900","720","1 000","30"],"correct_index":2,"explanation":"Each of three positions has 10 choices. Multiply 10×10×10. A code differs from a three-digit number because leading zero is allowed.","cognitive_level":{"code":"L2","label":"Routine procedures","band":"middle"}},{"question":"A regression fitted only to ages 12–18 predicts a person's height at age 80. Why should that prediction be treated cautiously?","options":["A fitted line guarantees accurate predictions at every age.","The slope proves age is the only cause of height.","It extrapolates far beyond the observed ages, where the relationship may change.","Regression cannot describe any association."],"correct_index":2,"explanation":"The model's observed age range is limited. A linear growth pattern during adolescence need not continue in adulthood, so substituting 80 does not validate the prediction.","cognitive_level":{"code":"L3","label":"Complex procedures","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","math"],"metadata":{"term":4,"focus":"Mixed revision: Geometry and differential calculus; Finance, regression and counting","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20MATHEMATICS%20_%20GR%2010-12%20_%20Web_1133.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/math-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge","Routine procedures","Complex procedures","Problem solving"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=_kS5tgxXQ0I%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"195db208-2206-54f7-8759-ebe19089fdce","title":"Mathematical Literacy · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"A floor plan uses 1:50. A door is 1.8 cm wide on the plan. Find the real width.","options":["9 m","0.9 m","0.09 m","90 m"],"correct_index":1,"explanation":"Multiply 1.8 cm by 50 = 90 cm = 0.9 m. Retain the same units until after scaling.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A delivery contract charges R250 plus R8 per kilometre. Find the cost for 35 km.","options":["R530","R280","R285","R8 750"],"correct_index":0,"explanation":"The distance cost is 8×35 = R280. Add the fixed R250 once: R530.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A salary rises from R8 000 to R8 600. Find the percentage increase.","options":["6.98%","75%","0.075%","7.5%"],"correct_index":3,"explanation":"Increase = R600. Divide by original salary: 600/8 000×100 = 7.5%.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A group has 12 learners; 7 are girls. One learner is selected fairly. P(not a girl) = ?","options":["5/12","7/12","5/7","1/12"],"correct_index":0,"explanation":"There are 12−7=5 learners who are not girls. Use 5 favourable outcomes out of 12.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"An item costs R1 150 including 15% VAT. A shop removes VAT by deducting 15% of R1 150. Which judgement is correct?","options":["The method is correct and gives R977.50 before VAT.","Add 15% again to reverse VAT.","The method is wrong: divide by 1.15 to obtain R1 000.","The original price cannot be found from the information."],"correct_index":2,"explanation":"The inclusive amount represents 115% of the pre-VAT base. Subtracting 15% of the inclusive amount uses a larger base than the original VAT calculation.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","matlit"],"metadata":{"term":2,"focus":"Mixed revision: Plans, packaging and integrated practice; Exam revision: finance, data and probability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7eec3551-07e4-5b4f-956f-f05eee78fba8","title":"Mathematical Literacy · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"A rectangular floor is 6 m × 4 m. Tiles cover 0.25 m² each. Ignoring waste, how many tiles are needed?","options":["96","24","48","6"],"correct_index":0,"explanation":"Floor area = 24 m². Divide by area per tile: 24/0.25 = 96. The units cancel to a count.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A bus leaves at 22:45 and arrives next day at 05:15. Find the journey time.","options":["17 h 30 min","7 h 30 min","5 h 30 min","6 h 30 min"],"correct_index":3,"explanation":"From 22:45 to midnight is 1 h 15 min, then another 5 h 15 min. Add to get 6 h 30 min.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A salary rises from R8 000 to R8 600. Find the percentage increase.","options":["6.98%","75%","0.075%","7.5%"],"correct_index":3,"explanation":"Increase = R600. Divide by original salary: 600/8 000×100 = 7.5%.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A group has 12 learners; 7 are girls. One learner is selected fairly. P(not a girl) = ?","options":["5/12","7/12","5/7","1/12"],"correct_index":0,"explanation":"There are 12−7=5 learners who are not girls. Use 5 favourable outcomes out of 12.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"An item costs R1 150 including 15% VAT. A shop removes VAT by deducting 15% of R1 150. Which judgement is correct?","options":["The method is correct and gives R977.50 before VAT.","Add 15% again to reverse VAT.","The method is wrong: divide by 1.15 to obtain R1 000.","The original price cannot be found from the information."],"correct_index":2,"explanation":"The inclusive amount represents 115% of the pre-VAT base. Subtracting 15% of the inclusive amount uses a larger base than the original VAT calculation.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","matlit"],"metadata":{"term":3,"focus":"Mixed revision: Measurement, scale and route planning; Exam revision: finance, data and probability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"a5c240b6-8916-5c96-890b-1da1ead48d0b","title":"Mathematical Literacy · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Mathematical Literacy","grade":"Grade 12","questions":[{"question":"A rectangular floor is 6 m × 4 m. Tiles cover 0.25 m² each. Ignoring waste, how many tiles are needed?","options":["96","24","48","6"],"correct_index":0,"explanation":"Floor area = 24 m². Divide by area per tile: 24/0.25 = 96. The units cancel to a count.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A bus leaves at 22:45 and arrives next day at 05:15. Find the journey time.","options":["17 h 30 min","7 h 30 min","5 h 30 min","6 h 30 min"],"correct_index":3,"explanation":"From 22:45 to midnight is 1 h 15 min, then another 5 h 15 min. Add to get 6 h 30 min.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"A carton holds 4 rows of 6 cans in one layer and has 3 layers. How many cans fit?","options":["24","18","72","48"],"correct_index":2,"explanation":"Multiply rows × cans per row × layers: 4×6×3 = 72. Counting only one layer gives 24.","cognitive_level":{"code":"L2","label":"Applying routine procedures","band":"lower"}},{"question":"A rectangular parcel is 40 cm × 30 cm × 20 cm. Find its volume.","options":["2 400 cm³","5 200 cm³","90 cm³","24 000 cm³"],"correct_index":3,"explanation":"Multiply all three dimensions: 40×30×20 = 24 000 cm³. Adding lengths does not calculate volume.","cognitive_level":{"code":"L3","label":"Applying multi-step procedures","band":"middle"}},{"question":"Contract A charges R250+R8/km; B charges R100+R12/km. A driver says B is always cheaper because its fixed charge is lower. What happens at 50 km?","options":["B costs R700 and is R50 cheaper than A.","Both cost R650.","A costs R650 and is R50 cheaper than B.","A costs R400 because the fixed charge is ignored."],"correct_index":2,"explanation":"A=250+8×50=R650. B=100+12×50=R700. A smaller fixed charge need not produce a smaller total once the distance charge is considered.","cognitive_level":{"code":"L4","label":"Reasoning and reflecting","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","matlit"],"metadata":{"term":4,"focus":"Mixed revision: Measurement, scale and route planning; Plans, packaging and integrated practice","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=q8-SkGy43rw%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/matlit-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing","Applying routine procedures","Applying multi-step procedures","Reasoning and reflecting"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=X4ZvlGUQ0vY%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"ffcf63eb-816f-5818-8440-5b9101ea2ceb","title":"Physical Sciences · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A cell has emf 12 V and internal resistance 1 Ω. It supplies 2 A. Find its terminal potential difference.","options":["14 V","12 V","10 V","6 V"],"correct_index":2,"explanation":"V=ε−Ir=12−2×1=10 V while supplying current. The internal resistor accounts for the lost volts.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"A generator converts predominantly which energy into electrical energy?","options":["Electrical energy into chemical energy","Mechanical energy","Nuclear energy directly with no process","Sound energy only"],"correct_index":1,"explanation":"Relative motion in a magnetic field induces emf. Mechanical input drives the generator, transferring energy to the electrical circuit.","cognitive_level":{"code":"L1","label":"Recall","band":"lower"}},{"question":"Find the pH of a strong monoprotic acid with [H₃O⁺] = 1 × 10⁻³ mol·dm⁻³.","options":["3","−3","11","0.001"],"correct_index":0,"explanation":"pH=−log₁₀[H₃O⁺]=−log₁₀(10⁻³)=3. The minus sign reverses the exponent's sign.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"For an exothermic forward reaction, increasing temperature shifts equilibrium towards…","options":["Products","Reactants","Both sides equally in composition","The catalyst"],"correct_index":1,"explanation":"Heat is effectively a product in an exothermic reaction. Increasing temperature favours the endothermic reverse reaction, increasing the proportion of reactants.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A trolley's momentum changes by 6 kg·m·s⁻¹. Two bumpers produce this same change in 0.1 s and 0.3 s. Which safety argument is justified?","options":["The 0.3 s bumper gives three times the average net force.","Both average forces must be equal because impulse is equal.","The 0.3 s bumper gives one third of the average net force.","Longer stopping time must increase the momentum change."],"correct_index":2,"explanation":"Average net force is impulse divided by contact time. The same 6 N·s gives 60 N over 0.1 s and 20 N over 0.3 s; longer time lowers the average force.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","phsc"],"metadata":{"term":2,"focus":"Mixed revision: Electric circuits, photoelectric effect and cells; Physics and chemistry examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"48f8cbb1-404d-525d-a41c-18ea2dfed684","title":"Physical Sciences · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A constant 20 N force acts parallel to a 3 m displacement. Find the work done by this force.","options":["6.67 J","60 J","23 J","0 J"],"correct_index":1,"explanation":"W=FΔx cosθ. Here θ=0°, so cosθ=1 and W=20×3=60 J. Only the parallel component does work.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"What does a catalyst change in a reaction at equilibrium?","options":["The rates of both forward and reverse reactions, not the equilibrium constant at fixed temperature","The equilibrium constant at unchanged temperature","Only the forward rate","The final equilibrium composition by itself"],"correct_index":0,"explanation":"A catalyst offers a lower-activation-energy pathway for both directions. Equilibrium is reached faster without shifting its position at the same temperature.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"Find the pH of a strong monoprotic acid with [H₃O⁺] = 1 × 10⁻³ mol·dm⁻³.","options":["3","−3","11","0.001"],"correct_index":0,"explanation":"pH=−log₁₀[H₃O⁺]=−log₁₀(10⁻³)=3. The minus sign reverses the exponent's sign.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"For an exothermic forward reaction, increasing temperature shifts equilibrium towards…","options":["Products","Reactants","Both sides equally in composition","The catalyst"],"correct_index":1,"explanation":"Heat is effectively a product in an exothermic reaction. Increasing temperature favours the endothermic reverse reaction, increasing the proportion of reactants.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A trolley's momentum changes by 6 kg·m·s⁻¹. Two bumpers produce this same change in 0.1 s and 0.3 s. Which safety argument is justified?","options":["The 0.3 s bumper gives three times the average net force.","Both average forces must be equal because impulse is equal.","The 0.3 s bumper gives one third of the average net force.","Longer stopping time must increase the momentum change."],"correct_index":2,"explanation":"Average net force is impulse divided by contact time. The same 6 N·s gives 60 N over 0.1 s and 20 N over 0.3 s; longer time lowers the average force.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","phsc"],"metadata":{"term":3,"focus":"Mixed revision: Work, Doppler effect and equilibrium; Physics and chemistry examination revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"bf31b6b7-063a-52b9-9532-f8587fdf5de9","title":"Physical Sciences · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Physical Sciences","grade":"Grade 12","questions":[{"question":"A constant 20 N force acts parallel to a 3 m displacement. Find the work done by this force.","options":["6.67 J","60 J","23 J","0 J"],"correct_index":1,"explanation":"W=FΔx cosθ. Here θ=0°, so cosθ=1 and W=20×3=60 J. Only the parallel component does work.","cognitive_level":{"code":"L3","label":"Analysis and application","band":"middle"}},{"question":"What does a catalyst change in a reaction at equilibrium?","options":["The rates of both forward and reverse reactions, not the equilibrium constant at fixed temperature","The equilibrium constant at unchanged temperature","Only the forward rate","The final equilibrium composition by itself"],"correct_index":0,"explanation":"A catalyst offers a lower-activation-energy pathway for both directions. Equilibrium is reached faster without shifting its position at the same temperature.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"In a galvanic cell, oxidation occurs at the…","options":["Cathode","Salt bridge only","Voltmeter","Anode"],"correct_index":3,"explanation":"Oxidation always occurs at the anode and reduction at the cathode. In a galvanic cell, electrons flow externally from anode to cathode.","cognitive_level":{"code":"L1","label":"Recall","band":"lower"}},{"question":"Light below a metal's threshold frequency shines on it. Increasing intensity alone will…","options":["Not cause photoemission in the standard single-photon model","Always eject electrons immediately","Increase each photon's frequency","Reduce the metal's work function to zero"],"correct_index":0,"explanation":"Each photon's energy is hf. Below threshold, individual photons lack enough energy to eject electrons; greater intensity does not raise their frequency.","cognitive_level":{"code":"L2","label":"Comprehension","band":"lower"}},{"question":"A metal emits no electrons under light below its threshold frequency. Which experiment best distinguishes the photon model from an intensity-only explanation?","options":["Change metal, frequency and intensity together with no record.","Count electrons once without measuring the light.","Keep frequency below threshold and increase intensity; then raise frequency above threshold.","Assume all bright light must eject electrons."],"correct_index":2,"explanation":"Below threshold, extra intensity alone does not cause standard single-photon emission. Crossing the frequency threshold tests the photon-energy condition while staged changes avoid confounding variables.","cognitive_level":{"code":"L4","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","phsc"],"metadata":{"term":4,"focus":"Mixed revision: Work, Doppler effect and equilibrium; Electric circuits, photoelectric effect and cells","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=uVcOcx728Y8%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/phsc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Recall","Comprehension","Analysis and application","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=DXUcPsguELw%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"e0838b14-a1ec-561d-b9ad-7bc653462657","title":"Life Sciences · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"A population has inherited variation in beak size. A food change favours larger beaks. What explains larger beaks becoming more common over generations?","options":["Every bird consciously enlarges its beak","The environment directly rewrites every bird's genes in the same way","Individuals evolve because they need to survive","Individuals with advantageous inherited traits leave more surviving offspring"],"correct_index":3,"explanation":"Natural selection acts on existing heritable variation. Changes in reproductive success alter trait frequencies across generations, not by individual intention.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Which finding supports an African origin of modern humans?","options":["The claim that living humans belong to separate biological races ranked by ability","The claim that evolution stopped outside Africa","Fossil and genetic evidence consistent with early modern humans in Africa and later dispersal","The absence of all fossils outside Africa"],"correct_index":2,"explanation":"The Out-of-Africa model is supported by multiple lines of fossil and genetic evidence. It does not rank living populations or deny later migration and interbreeding.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"Why does meiosis contribute to variation?","options":["It produces only genetically identical gametes","Crossing over and independent assortment produce different allele combinations","It doubles chromosome number in each gamete","It eliminates all mutations"],"correct_index":1,"explanation":"Crossing over and independent chromosome assortment create different combinations. Meiosis also halves chromosome number for sexual reproduction.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A healthy person becomes dehydrated. Which response helps conserve water?","options":["Decreased ADH and unlimited water loss","Kidneys stop responding to hormones permanently","Increased ADH and increased kidney water reabsorption","More dilute urine in every circumstance"],"correct_index":2,"explanation":"Dehydration generally stimulates ADH release, promoting water reabsorption and smaller volumes of concentrated urine.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A pesticide kills 95% of insects. Survivors produce offspring that also resist it. What control-study evidence would strengthen an inherited-resistance explanation?","options":["Every survivor is assumed to have chosen resistance.","Only the pesticide bottle's colour is recorded.","Resistance persists in offspring raised without pesticide and differs from a susceptible comparison line.","No offspring are tested because survival proves inheritance."],"correct_index":2,"explanation":"Raising offspring without exposure helps distinguish inherited resistance from an immediate environmental response. A susceptible comparison and repeated trials strengthen the interpretation.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","lisc"],"metadata":{"term":2,"focus":"Mixed revision: Evolution and interpreting evidence; Integrated biological reasoning revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"238bf82e-2165-57a1-a97e-2d3cd3c95245","title":"Life Sciences · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"In a monohybrid cross Aa × Aa with complete dominance, P(aa) is…","options":["1/2","3/4","1/4","1"],"correct_index":2,"explanation":"The four equally likely combinations are AA, Aa, Aa and aa. Only one is homozygous recessive.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"A shoot bends towards light. What is this response called?","options":["Negative phototropism","Positive phototropism","Positive geotropism only","Transpiration"],"correct_index":1,"explanation":"Phototropism is growth in response to directional light. Growth towards the stimulus is positive; differential growth causes the bending.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"Why does meiosis contribute to variation?","options":["It produces only genetically identical gametes","Crossing over and independent assortment produce different allele combinations","It doubles chromosome number in each gamete","It eliminates all mutations"],"correct_index":1,"explanation":"Crossing over and independent chromosome assortment create different combinations. Meiosis also halves chromosome number for sexual reproduction.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A healthy person becomes dehydrated. Which response helps conserve water?","options":["Decreased ADH and unlimited water loss","Kidneys stop responding to hormones permanently","Increased ADH and increased kidney water reabsorption","More dilute urine in every circumstance"],"correct_index":2,"explanation":"Dehydration generally stimulates ADH release, promoting water reabsorption and smaller volumes of concentrated urine.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"A pesticide kills 95% of insects. Survivors produce offspring that also resist it. What control-study evidence would strengthen an inherited-resistance explanation?","options":["Every survivor is assumed to have chosen resistance.","Only the pesticide bottle's colour is recorded.","Resistance persists in offspring raised without pesticide and differs from a susceptible comparison line.","No offspring are tested because survival proves inheritance."],"correct_index":2,"explanation":"Raising offspring without exposure helps distinguish inherited resistance from an immediate environmental response. A susceptible comparison and repeated trials strengthen the interpretation.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","lisc"],"metadata":{"term":3,"focus":"Mixed revision: Inheritance and human responses; Integrated biological reasoning revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"1330c94a-7ff1-5218-897f-1726ce49d224","title":"Life Sciences · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Life Sciences","grade":"Grade 12","questions":[{"question":"In a monohybrid cross Aa × Aa with complete dominance, P(aa) is…","options":["1/2","3/4","1/4","1"],"correct_index":2,"explanation":"The four equally likely combinations are AA, Aa, Aa and aa. Only one is homozygous recessive.","cognitive_level":{"code":"L3","label":"Applying scientific knowledge","band":"middle"}},{"question":"A shoot bends towards light. What is this response called?","options":["Negative phototropism","Positive phototropism","Positive geotropism only","Transpiration"],"correct_index":1,"explanation":"Phototropism is growth in response to directional light. Growth towards the stimulus is positive; differential growth causes the bending.","cognitive_level":{"code":"L1","label":"Knowing science","band":"lower"}},{"question":"What is required for populations to become separate species through reproductive isolation?","options":["They cease exchanging genes and diverge sufficiently","They must become identical in every feature","They must live on different planets","Every isolated individual must die"],"correct_index":0,"explanation":"Restricted gene flow allows divergence. Speciation involves reproductive isolation, not simply living far apart for a short time.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"How do homologous structures support common ancestry?","options":["They must perform identical functions","They share an underlying structural pattern despite possible differences in function","They prove organisms are the same species","They arise only from identical environments"],"correct_index":1,"explanation":"Shared underlying structure is consistent with descent from a common ancestor, modified for different uses. Similar function alone can instead reflect analogy.","cognitive_level":{"code":"L2","label":"Understanding science","band":"lower"}},{"question":"After drought, large-beaked birds become more common. Which additional evidence best supports natural selection rather than a temporary change within individuals?","options":["Each bird reports trying harder to grow a beak.","Only the population's location is recorded.","Beak-size variation is inherited and larger-beaked birds leave more surviving offspring.","A single adult changes its posture for a photograph."],"correct_index":2,"explanation":"Natural selection requires heritable variation and differential reproductive success. A change in frequency alone needs evidence linking the trait to inheritance and survival or reproduction.","cognitive_level":{"code":"L4","label":"Evaluating, analysing and synthesising","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","lisc"],"metadata":{"term":4,"focus":"Mixed revision: Inheritance and human responses; Evolution and interpreting evidence","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=_yUNfV0A_8o%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/lisc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowing science","Understanding science","Applying scientific knowledge","Evaluating, analysing and synthesising"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=c5UFxlh6dx4%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"3b73bec0-79e1-576d-8af5-fc763e5b1ba7","title":"Accounting · Grade 12 · Term 2 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 12","questions":[{"question":"For this exercise output VAT is R18 000 and deductible input VAT R11 000. What is payable?","options":["R7 000","R29 000","R11 000","R18 000"],"correct_index":0,"explanation":"Net VAT payable = output−deductible input = 18 000−11 000 = R7 000, assuming no other adjustments.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A budget forecast shows a cash shortfall next month. Which response is most useful?","options":["Ignore it until every supplier is overdue","Treat the forecast as a guaranteed bank balance","Record an imaginary cash receipt","Investigate timing, reduce avoidable payments and plan funding early"],"correct_index":3,"explanation":"A cash forecast is an early warning. Review assumptions and practical actions; fabricating receipts hides rather than solves the problem.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A company has current assets R300 000 and liabilities due within a year R200 000. Find the current ratio.","options":["0.67:1","3:1","1.5:1","2:1"],"correct_index":2,"explanation":"Current ratio = current assets/current liabilities = 300 000/200 000=1.5:1. Assess stock quality and collection timing as well.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a bank reconciliation investigate unexplained differences?","options":["All differences are automatically bank fraud","Reconciliation changes the bank's actual cash without evidence","A bank statement never contains errors","They may reveal recording errors, timing differences or unauthorised transactions"],"correct_index":3,"explanation":"Reconciliation compares independent records. Identify and substantiate each difference before recording any necessary correction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business repays a R40 000 loan and its current ratio worsens. A director calls the repayment an expense that reduced profit. Which evaluation is sound?","options":["Principal repayment always reduces profit by R40 000.","Loan repayment creates R40 000 revenue.","Loan principal reduces cash and liabilities; assess liquidity separately from interest expense.","A lower current ratio necessarily proves fraud."],"correct_index":2,"explanation":"Repayment of principal reduces an asset and a liability, rather than being an operating expense. Interest is accounted for separately; the remaining cash and liability classification affect liquidity analysis.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","acc"],"metadata":{"term":2,"focus":"Mixed revision: VAT and forward-looking budgets; Integrated financial and control revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"7988a79c-e3cd-5e78-8b76-7b2f2fa069c4","title":"Accounting · Grade 12 · Term 3 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 12","questions":[{"question":"A FIFO system has 10 units at R20, followed by 10 at R30. Twelve units are sold. Find cost of sales.","options":["R300","R340","R360","R260"],"correct_index":3,"explanation":"FIFO issues the oldest units first: 10×20 + 2×30 = R260. The remaining eight units are from the R30 batch.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why separate asset custody from record keeping where practical?","options":["To guarantee fraud is impossible","To avoid all asset registers","To reduce the risk of undetected error or fraud","To make records confidential from auditors"],"correct_index":2,"explanation":"Segregation of duties makes unauthorised actions harder to conceal. It reduces risk but requires checks and does not eliminate every risk.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A company has current assets R300 000 and liabilities due within a year R200 000. Find the current ratio.","options":["0.67:1","3:1","1.5:1","2:1"],"correct_index":2,"explanation":"Current ratio = current assets/current liabilities = 300 000/200 000=1.5:1. Assess stock quality and collection timing as well.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why should a bank reconciliation investigate unexplained differences?","options":["All differences are automatically bank fraud","Reconciliation changes the bank's actual cash without evidence","A bank statement never contains errors","They may reveal recording errors, timing differences or unauthorised transactions"],"correct_index":3,"explanation":"Reconciliation compares independent records. Identify and substantiate each difference before recording any necessary correction.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A business repays a R40 000 loan and its current ratio worsens. A director calls the repayment an expense that reduced profit. Which evaluation is sound?","options":["Principal repayment always reduces profit by R40 000.","Loan repayment creates R40 000 revenue.","Loan principal reduces cash and liabilities; assess liquidity separately from interest expense.","A lower current ratio necessarily proves fraud."],"correct_index":2,"explanation":"Repayment of principal reduces an asset and a liability, rather than being an operating expense. Interest is accounted for separately; the remaining cash and liability classification affect liquidity analysis.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","acc"],"metadata":{"term":3,"focus":"Mixed revision: Inventory, assets and cost accounting; Integrated financial and control revision","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"e530c50d-2698-545d-8bfd-60e8fc846ab3","title":"Accounting · Grade 12 · Term 4 selection · Set B: Mixed revision","subject":"Accounting","grade":"Grade 12","questions":[{"question":"A FIFO system has 10 units at R20, followed by 10 at R30. Twelve units are sold. Find cost of sales.","options":["R300","R340","R360","R260"],"correct_index":3,"explanation":"FIFO issues the oldest units first: 10×20 + 2×30 = R260. The remaining eight units are from the R30 batch.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why separate asset custody from record keeping where practical?","options":["To guarantee fraud is impossible","To avoid all asset registers","To reduce the risk of undetected error or fraud","To make records confidential from auditors"],"correct_index":2,"explanation":"Segregation of duties makes unauthorised actions harder to conceal. It reduces risk but requires checks and does not eliminate every risk.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why does depreciation appear in a projected income statement but not as a cash-budget payment?","options":["It is always income","It is an expense without a current cash outflow","It is illegal in all budgets","It is paid to the bank every month"],"correct_index":1,"explanation":"The income statement forecasts profit using accrual expenses; a cash budget forecasts cash movements. Depreciation reduces profit without a cash payment in that period.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Credit sales are R50 000. The collection policy expects 80% next month, with no discount. Find next month's receipt from these sales.","options":["R10 000","R50 000","R40 000","R62 500"],"correct_index":2,"explanation":"Expected cash collection = 50 000×0.80 = R40 000. Record receipts in the month collected, not automatically when sold.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A profitable business forecasts a cash deficit because customers pay after supplier debts fall due. Which recommendation addresses the cause?","options":["Increase depreciation to generate immediate cash.","Ignore the deficit because profit guarantees positive bank funds.","Negotiate payment timing and improve collections while assessing suitable short-term funding.","Record unpaid customer invoices as cash already received."],"correct_index":2,"explanation":"The problem is the timing gap between receipts and payments. A cash forecast, collection action and negotiated terms address it; accrual profit and non-cash adjustments cannot guarantee immediate liquidity.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","acc"],"metadata":{"term":4,"focus":"Mixed revision: Inventory, assets and cost accounting; VAT and forward-looking budgets","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=IIU4LUlZBFM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/acc-12","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=g4DcPbejtts%3d&tabid=3205&portalid=0&mid=10755"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
